-- CPF Oracle V63 provision template
-- Password tokens are rendered only in-memory by the vendor executor and are never persisted.

BEGIN
    EXECUTE IMMEDIATE 'CREATE USER CPFDB IDENTIFIED BY "${CPFDB_PASSWORD}"';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -1920 THEN RAISE; END IF;
END;
/
GRANT CREATE SESSION, CREATE TABLE, CREATE VIEW, CREATE SEQUENCE, CREATE TRIGGER, CREATE PROCEDURE TO CPFDB;
ALTER USER CPFDB QUOTA UNLIMITED ON USERS;

